const input = require("fs").readFileSync(0, "utf8");
const [numText, word] = input.trim().split("\n");
const num = Number(numText);

function sumTo(n) {
  if (n === 0) {
    return 0;
  }
  return n + sumTo(n - 1);
}

function isPalindrome(str) {
  if (str.length <= 1) {
    return true;
  }
  if (str[0] !== str.at(-1)) {
    return false;
  }
  return isPalindrome(str.slice(1, -1));
}

console.log(`sumTo(${num}) = ${sumTo(num)}`);
console.log(`isPalindrome(${word}) = ${isPalindrome(word)}`);

steps.body:
An array shrinks the way a string does: handle the first item and recurse on the rest. Slicing works, but `arr.slice(1)` copies the rest on every call. Passing an index is cheaper: a default parameter starts it at 0.

```javascript
function sumArray(arr, i = 0) {
  if (i === arr.length) {
    return 0;
  }
  return arr[i] + sumArray(arr, i + 1);
}
```

Recursion really shines on **nested** data, where you cannot know how many loops to write. `Array.isArray(x)` tells an inner array apart from a number. Loop over the items, recurse into each inner array, and handle plain values directly:

```javascript
for (const item of arr) {
  total += Array.isArray(item) ? deepSum(item) : item;
}
```

The base case is hidden here: an array with no inner arrays makes no recursive calls. Use `Array.isArray`, not `typeof item === "object"` (true for `null` and plain objects too) or `item.length` (strings have a length too).

JavaScript also has a built-in flatten. `arr.flat()` removes one level of nesting, and `arr.flat(Infinity)` removes all of them. Use it in real code, and write your own when you need to count, sum, or check something along the way.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const data = JSON.parse(input);

function deepSum(arr) {
  let total = 0;
  for (const item of arr) {
    total += Array.isArray(item) ? deepSum(item) : item;
  }
  return total;
}

function flatten(arr) {
  const result = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      result.push(...flatten(item));
    } else {
      result.push(item);
    }
  }
  return result;
}

function sumArray(arr, i = 0) {
  if (i === arr.length) {
    return 0;
  }
  return arr[i] + sumArray(arr, i + 1);
}

const flat = flatten(data);
console.log(`deepSum = ${deepSum(data)}`);
console.log(`flatten = ${flat.join(",")}`);
console.log(`sumArray = ${sumArray(flat)}`);
console.log(`same as flat(Infinity): ${flat.join(",") === data.flat(Infinity).join(",")}`);

