const input = require("fs").readFileSync(0, "utf8");
const data = JSON.parse(input);

function countNumbers(arr) {
  let count = 0;
  for (const item of arr) {
    count += Array.isArray(item) ? countNumbers(item) : 1;
  }
  return count;
}

function largest(arr) {
  let best = -Infinity;
  for (const item of arr) {
    const value = Array.isArray(item) ? largest(item) : item;
    best = Math.max(best, value);
  }
  return best;
}

function flatten(arr) {
  const result = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      result.push(...flatten(item));
    } else {
      result.push(item);
    }
  }
  return result;
}

console.log(`count = ${countNumbers(data)}`);
console.log(`max = ${largest(data)}`);
console.log(`flat = ${flatten(data).join(",")}`);

steps.body:
The textbook Fibonacci is short but slow:

```javascript
function fib(n) {
  if (n < 2) {
    return n;
  }
  return fib(n - 1) + fib(n - 2);
}
```

Each call makes two more, so `fib(5)` computes `fib(3)` twice and `fib(2)` three times. The call count grows by about 1.6 times with every step of `n`. That is **exponential** time. Big O notation describes how the work grows as the input grows, and this growth is usually written O(2^n): `fib(40)` already makes over 300 million calls.

**Memoization** fixes it by remembering answers. Check a `Map` before doing any work, and store each new result:

```javascript
function memoFib(n, memo = new Map()) {
  if (n < 2) {
    return n;
  }
  if (memo.has(n)) {
    return memo.get(n);
  }
  const result = memoFib(n - 1, memo) + memoFib(n - 2, memo);
  memo.set(n, result);
  return result;
}
```

The default parameter creates a fresh `Map` for each outside call. **Pass `memo` along** in every recursive call, or each one gets a new empty map and nothing is saved. Now each `n` is computed once: **linear** time, O(n).

The same trick solves counting problems. Results past `fib(78)` exceed `Number.MAX_SAFE_INTEGER`, so switch to BigInt for bigger inputs.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const [naiveN, memoN] = input.trim().split(/\s+/).map(Number);

let calls = 0;

function fib(n) {
  calls++;
  if (n < 2) {
    return n;
  }
  return fib(n - 1) + fib(n - 2);
}

function memoFib(n, memo = new Map()) {
  if (n < 2) {
    return n;
  }
  if (memo.has(n)) {
    return memo.get(n);
  }
  const result = memoFib(n - 1, memo) + memoFib(n - 2, memo);
  memo.set(n, result);
  return result;
}

const naiveResult = fib(naiveN);
console.log(`naive fib(${naiveN}) = ${naiveResult} after ${calls} calls`);
console.log(`memo fib(${memoN}) = ${memoFib(memoN)}`);

